        const b = byId.get(edge.to);
        if (!a || !b) return null;
        const midY = (a.y + b.y) / 2;
        return (
          <path
            key={`${edge.from}-${edge.to}`}
            data-about-draw
            d={`M${a.x} ${a.y + 30} C ${a.x} ${midY}, ${b.x} ${midY}, ${b.x} ${b.y - 14}`}
