        const isStory = node.tier === "story";
        const isSource = node.tier === "source";
        return (
          <g key={node.id} textAnchor="middle">
            <circle
              cx={node.x}
              cy={node.y - 6}
              r={isStory ? 6 : isSource ? 4 : 3}
